WITH matched AS (SELECT s.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM promotions s INNER JOIN promotions pr ON s.channel = pr.channel AND s.starts_on >= pr.starts_on AND s.starts_on < pr.ends_on + INTERVAL 14 DAYS) SELECT CASE WHEN promo_id >= 11 THEN 'PREMIUM' ELSE 'STANDARD' END AS promo_id_tier, CASE WHEN promotion_discount_pct >= 0.29 THEN 'HIGH' ELSE 'LOW' END AS promotion_discount_pct_tier, promo_code, ROUND(SUM(promo_id) / NULLIF(COUNT(CASE WHEN promotion_promo_code = 'BUNDLE' THEN 1 END), 0), 2) AS promo_id_per_bundle, SUM(discount_pct) FILTER (WHERE promotion_promo_code = 'SPRING10') AS spring10_total_discount_pct, ROUND(AVG(promo_id), 2) AS avg_promo_id FROM matched GROUP BY ROLLUP (CASE WHEN promo_id >= 11 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN promotion_discount_pct >= 0.29 THEN 'HIGH' ELSE 'LOW' END, promo_code);
